// FAQ knowledge base
const faqs = [
  {
    keywords: ["hours", "open", "working hours", "when are you open"],
    answer: "We are open Monday to Friday, 9 AM to 6 PM Eastern Time."
  },
  {
    keywords: ["contact", "email", "phone", "call"],
    answer: "You can email us at help@company.com or call 1-800-555-0123."
  },
  {
    keywords: ["services", "offer", "provide", "what do you do"],
    answer: "We offer web design, app development, and digital marketing services."
  },
  {
    keywords: ["pricing", "cost", "price", "charges"],
    answer: "Our basic package starts at $99 per month. Contact us for custom pricing."
  },
  {
    keywords: ["location", "where", "address"],
    answer: "We are located in New York City, but we serve clients nationwide."
  },
  {
    keywords: ["support", "help", "technical", "issue"],
    answer: "For technical support, email support@company.com or call our helpline."
  }
];

// Safely extract input
const input = $input.all()[0].json;
const userQuestion = String(
  input.message?.content || 
  input.transcript || 
  input.query || ""
).toLowerCase();

console.log("User asked:", userQuestion);

// Matching logic
function findAnswer(question) {
  for (const faq of faqs) {
    for (const keyword of faq.keywords) {
      if (question.includes(keyword)) {
        return faq.answer;
      }
    }
  }
  return "I don't have that information right now. Please contact our support team at help@company.com for assistance.";
}

const response = findAnswer(userQuestion);

// Output response
return {
  json: {
    answer: response,
    question: userQuestion,
    timestamp: new Date().toISOString()
  }
};
